$n=0;function check($x,$m){global $n;if(!$x)throw new RuntimeException($m);$n++;}function requestFor($data){return Request::create('/test','POST',$data+['_request_key'=>(string)Str::uuid()],[],[],['HTTP_ACCEPT'=>'application/json']);}function invalid($fn,$m){try{$fn();throw new RuntimeException($m);}catch(ValidationException $e){check(true,$m);}}
$c=new SellerPromotionController;$offer=['product_id'=>1,'type'=>'sale','price'=>80,'starts_at'=>'2026-11-02T12:00:00','ends_at'=>'2026-11-05T12:00:00'];$req=requestFor($offer);$c->offer($req);$c->offer($req);check(DB::table('promotions')->count()===1,'Repeated submission does not duplicate offer');
